pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address newOwner) internal {
        bool callOk = true;
        bool returnedSuccess = false;
        try c.setOwner(newOwner) returns (bool s) {
            returnedSuccess = s;
        } catch {
            callOk = false;
        }
        address observedOwner;
        try c.owner() returns (address __r) { observedOwner = __r; } catch { return; }
        assertTrue(callOk && (observedOwner == newOwner || (!returnedSuccess && observedOwner == address(this))));
    }

